        <QueryBuilderRule Condition="and" Rules="
        new List<RuleModel> {
            new RuleModel { Field = "EmployeeID", Label="Employee ID", Operator="equal", Type="number", Value=1001 }
        }"></QueryBuilderRule>
   </QueryBuilderRules>
</SfQueryBuilder>
